"use client"

import * as React from "react"

import { PlainTextViewerFrame } from "./plain-text-viewer-frame"
import { TextViewerFallback } from "./text-viewer-chrome"
import { TextViewerContent } from "./text-viewer-content"
import type { TextViewerHandle, TextViewerProps } from "./text-viewer-types"

export type {
  TextDocumentSource,
  TextLineRange,
  TextViewerHandle,
  TextViewerProps,
} from "./text-viewer-types"

export const TextViewer = React.forwardRef<TextViewerHandle, TextViewerProps>(
  function TextViewer(props, ref) {
    return (
      <PlainTextViewerFrame
        props={props}
        forwardedRef={ref}
        clientFallbackPolicy="always"
        Fallback={TextViewerFallback}
        Content={TextViewerContent}
      />
    )
  }
)

"use client"

import * as React from "react"
import { Check, Copy } from "lucide-react"

import { type ViewerDownloadAction } from "@/lib/viewer-download"

import { Skeleton } from "./skeleton"
import { TextCodeViewerFrame } from "./text-code-viewer-chrome"
import {
  ViewerToolbar,
  ViewerToolbarButton,
  ViewerToolbarSkeleton,
} from "./viewer-toolbar"

export function TextViewerFrame({
  className,
  bare,
  children,
}: {
  className?: string
  bare?: boolean
  children: React.ReactNode
}) {
  return (
    <TextCodeViewerFrame
      bare={bare}
      bareClassName="h-full bg-background"
      className={className}
      dataSlot="text-viewer"
      framedClassName="rounded-xl border bg-background"
    >
      {children}
    </TextCodeViewerFrame>
  )
}

export function TextViewerFallback({
  className,
  toolbar = true,
  bare,
}: {
  className?: string
  toolbar?: boolean
  bare?: boolean
}) {
  return (
    <TextViewerFrame className={className} bare={bare}>
      {toolbar ? <ViewerToolbarSkeleton title zoom download /> : null}
      <div
        className="min-h-0 flex-1 space-y-3 overflow-hidden p-5"
        data-slot="text-body-skeleton"
      >
        {Array.from({ length: 10 }, (_, index) => (
          <Skeleton
            key={index}
            className="h-4"
            style={{ width: `${48 + ((index * 17) % 44)}%` }}
          />
        ))}
      </div>
    </TextViewerFrame>
  )
}

export function TextViewerToolbar({
  wordCount,
  fontScale,
  copyText,
  copyLabel = "Copy text",
  downloadAction,
  leading,
  onZoomOut,
  onZoomIn,
  onResetZoom,
}: {
  wordCount: number
  fontScale: number
  copyText?: string
  copyLabel?: string
  downloadAction: ViewerDownloadAction
  leading?: React.ReactNode
  onZoomOut: () => void
  onZoomIn: () => void
  onResetZoom: () => void
}) {
  return (
    <ViewerToolbar
      title={leading ?? `${wordCount} word${wordCount === 1 ? "" : "s"}`}
      zoom={{
        scale: fontScale,
        onZoomOut,
        onZoomIn,
        onFit: onResetZoom,
        fitLabel: "Reset zoom",
      }}
      downloads={[downloadAction]}
      extra={
        copyText == null ? null : (
          <TextViewerCopyControl label={copyLabel} text={copyText} />
        )
      }
    />
  )
}

function TextViewerCopyControl({
  label,
  text,
}: {
  label: string
  text: string
}) {
  const [isCopied, setIsCopied] = React.useState(false)
  const timeoutRef = React.useRef<number | null>(null)

  React.useEffect(
    () => () => {
      if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current)
    },
    []
  )

  const copyText = () => {
    if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current)

    try {
      const result = navigator.clipboard?.writeText(text)
      void Promise.resolve(result).then(() => {
        setIsCopied(true)
        timeoutRef.current = window.setTimeout(() => {
          timeoutRef.current = null
          setIsCopied(false)
        }, 1200)
      })
    } catch {
      setIsCopied(false)
    }
  }

  return (
    <ViewerToolbarButton
      label={isCopied ? "Copied" : label}
      onClick={copyText}
      type="button"
    >
      {isCopied ? <Check /> : <Copy />}
    </ViewerToolbarButton>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

export function TextCodeViewerFrame({
  bare,
  bareClassName,
  children,
  className,
  dataSlot,
  framedClassName,
}: {
  bare?: boolean
  bareClassName: string
  children: React.ReactNode
  className?: string
  dataSlot: string
  framedClassName: string
}) {
  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? bareClassName : framedClassName,
        className
      )}
      data-slot={dataSlot}
    >
      {children}
    </div>
  )
}

"use client"

import * as React from "react"

import {
  isResourceError,
  isViewerFormatError,
  isViewerStateError,
  isViewerUnsupportedError,
  ViewerFormatError,
} from "@/lib/viewer-errors"
import {
  createViewerResource,
  type ViewerContentIdentity,
  type ViewerResource,
} from "@/lib/viewer-resource"
import type {
  BlobViewerSource,
  TextSource,
  UrlViewerSource,
} from "@/lib/viewer-source"

import {
  DEFAULT_MAX_BYTES,
  DEFAULT_MAX_LINES,
  type TextViewerBounds,
} from "./plain-text-resource"
import { useIsClient } from "./use-is-client"
import { ViewerErrorBoundary } from "./viewer-error"

type TextResourceSource = UrlViewerSource | BlobViewerSource | TextSource
type ClientFallbackPolicy = "always" | "non-inline-source"

export interface PlainTextViewerFrameProps<
  THandle,
  TProps extends PlainTextViewerFramePublicProps,
> {
  props: TProps
  forwardedRef: React.ForwardedRef<THandle>
  clientFallbackPolicy: ClientFallbackPolicy
  Fallback: React.ComponentType<PlainTextViewerFallbackProps>
  Content: React.ComponentType<
    TProps & {
      resource: ViewerResource
      retryVersion: number
      forwardedRef?: React.ForwardedRef<THandle>
    }
  >
}

export interface PlainTextViewerFramePublicProps extends TextViewerBounds {
  source: TextResourceSource
  className?: string
  toolbar?: boolean
  bare?: boolean
}

export interface PlainTextViewerFallbackProps {
  className?: string
  toolbar?: boolean
  bare?: boolean
}

export function PlainTextViewerFrame<
  THandle,
  TProps extends PlainTextViewerFramePublicProps,
>({
  props,
  forwardedRef,
  clientFallbackPolicy,
  Fallback,
  Content,
}: PlainTextViewerFrameProps<THandle, TProps>) {
  const [retryState, setRetryState] = React.useState({
    contentKey: "",
    version: 0,
  })
  const isClient = useIsClient()
  const { source } = props
  const resource = React.useMemo(() => createViewerResource(source), [source])
  const contentBaseKey = plainTextViewerContentBaseKey(resource.content, props)
  const retryVersion =
    retryState.contentKey === contentBaseKey ? retryState.version : 0
  const resetKey = plainTextViewerResetKey(resource, props, retryVersion)
  const contentResetKey = plainTextViewerContentResetKey(
    contentBaseKey,
    retryVersion
  )

  if (!isClient && shouldRenderClientFallback(clientFallbackPolicy, source)) {
    return (
      <Fallback
        className={props.className}
        toolbar={props.toolbar}
        bare={props.bare}
      />
    )
  }

  return (
    <ViewerErrorBoundary
      bare={props.bare}
      className={props.className}
      download={
        props.toolbar === false ? null : plainTextViewerDownloadAction(resource)
      }
      format="text"
      mapError={plainTextViewerBoundaryError}
      resetKey={resetKey}
      sourceKind={resource.sourceKind}
      onRetry={() =>
        setRetryState((state) => ({
          contentKey: contentBaseKey,
          version: state.contentKey === contentBaseKey ? state.version + 1 : 1,
        }))
      }
    >
      <React.Suspense
        key={contentResetKey}
        fallback={
          <Fallback
            className={props.className}
            toolbar={props.toolbar}
            bare={props.bare}
          />
        }
      >
        <Content
          {...props}
          forwardedRef={forwardedRef}
          retryVersion={retryVersion}
          resource={resource}
        />
      </React.Suspense>
    </ViewerErrorBoundary>
  )
}

function plainTextViewerDownloadAction(resource: ViewerResource) {
  return resource.originalDownload
}

function plainTextViewerBoundaryError(error: unknown) {
  if (
    isResourceError(error) ||
    isViewerFormatError(error) ||
    isViewerStateError(error) ||
    isViewerUnsupportedError(error)
  ) {
    return error
  }

  return new ViewerFormatError({
    format: "text",
    kind: "render_failed",
    message: "Failed to render text.",
    cause: error,
  })
}

function plainTextViewerResetKey(
  resource: ViewerResource,
  props: Pick<PlainTextViewerFramePublicProps, "maxBytes" | "maxLines">,
  retryVersion: number
): string {
  const [maxBytesKey, maxLinesKey] = plainTextViewerBoundsResetKey(props)
  return [resource.keys.resource, retryVersion, maxBytesKey, maxLinesKey].join(
    "\u0000"
  )
}

function plainTextViewerContentResetKey(
  contentBaseKey: string,
  retryVersion: number
): string {
  return [contentBaseKey, retryVersion].join("\u0000")
}

function plainTextViewerContentBaseKey(
  content: ViewerContentIdentity,
  props: Pick<PlainTextViewerFramePublicProps, "maxBytes" | "maxLines">
): string {
  const [maxBytesKey, maxLinesKey] = plainTextViewerBoundsResetKey(props)
  return [content.key, maxBytesKey, maxLinesKey].join("\u0000")
}

function plainTextViewerBoundsResetKey(
  props: Pick<PlainTextViewerFramePublicProps, "maxBytes" | "maxLines">
) {
  return [
    plainTextViewerBoundResetKeyPart(props.maxBytes, DEFAULT_MAX_BYTES),
    plainTextViewerBoundResetKeyPart(props.maxLines, DEFAULT_MAX_LINES),
  ] as const
}

function plainTextViewerBoundResetKeyPart(
  value: number | undefined,
  defaultValue: number
) {
  return String(value === undefined ? defaultValue : value)
}

function shouldRenderClientFallback(
  policy: ClientFallbackPolicy,
  source: TextResourceSource
) {
  return policy === "always" || source.kind !== "text"
}

"use client"

import * as React from "react"
import { Check, Copy } from "lucide-react"

import { cn } from "@/lib/utils"
import type { ViewerResource } from "@/lib/viewer-resource"

import { ScrollArea } from "./scroll-area"
import { TextViewerFrame, TextViewerToolbar } from "./text-viewer-chrome"
import {
  createPreparedTextDocument,
  getCodeVisibleLineWindow,
  getInlineVisibleLineWindow,
  getTableVisibleRowWindow,
  layoutTextDocument,
  materializeCodeVisibleLines,
  materializeInlineVisibleLines,
  resolveTextViewerMode,
  serializeMarkdownTableForClipboard,
  textFrameIntersectsLineRange,
  type CodeTextBlockFrame,
  type ImageTextBlockFrame,
  type InlineTextBlockFrame,
  type PreparedCodeTextBlock,
  type PreparedImageTextBlock,
  type PreparedInlineTextBlock,
  type PreparedRuleTextBlock,
  type PreparedTableTextBlock,
  type PreparedTextBlock,
  type PreparedTextDocument,
  type RuleTextBlockFrame,
  type TableRowWindow,
  type TableTextBlockFrame,
  type TextBlockFrame,
  type TextDocumentFrame,
  type TextLineWindow,
} from "./text-viewer-layout"
import { isLineInRange, normalizeTextLineRange } from "./text-viewer-ranges"
import {
  readTextResource,
  resolvedTextViewerBounds,
} from "./text-viewer-resource"
import {
  clampTextViewerScale,
  TEXT_VIEWER_BLOCK_PADDING,
} from "./text-viewer-scale"
import type { TextViewerHandle, TextViewerProps } from "./text-viewer-types"
import {
  getTextFrameScrollAnchor,
  getTextFrameVirtualItems,
  useTextVirtualViewport,
  type TextFrameScrollAnchor,
} from "./text-viewer-virtualization"

const TEXT_VIEWER_HORIZONTAL_PADDING = 16
const TEXT_VIEWER_INITIAL_TEXT_WIDTH = 768
const TEXT_VIEWER_OVERSCAN_PX = 320

export function TextViewerContent({
  resource,
  className,
  toolbar = true,
  highlight,
  bare = false,
  maxBytes,
  maxLines,
  retryVersion,
  forwardedRef,
  mode: forcedMode,
}: TextViewerProps & {
  resource: ViewerResource
  retryVersion: number
  forwardedRef?: React.ForwardedRef<TextViewerHandle>
}) {
  const bounds = React.useMemo(
    () => resolvedTextViewerBounds({ maxBytes, maxLines }),
    [maxBytes, maxLines]
  )
  const text = React.useMemo(
    () =>
      readTextResource({
        bounds,
        content: resource.content,
        retryVersion,
      }),
    [bounds, resource.content, retryVersion]
  )
  const mode = React.useMemo(
    () =>
      forcedMode ??
      resolveTextViewerMode({
        fileName: resource.fileName,
        mimeType: resource.content.mimeType,
      }),
    [forcedMode, resource.content.mimeType, resource.fileName]
  )
  const downloadAction = React.useMemo(
    () => resource.originalDownload,
    [resource]
  )

  const [fontScale, setFontScale] = React.useState(1)
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const pendingScrollAnchorRef = React.useRef<TextFrameScrollAnchor | null>(
    null
  )
  const viewport = useTextVirtualViewport(viewportRef)
  const viewportHeight = viewport.clientHeight || 600
  const viewportWidth = viewport.clientWidth || 800
  const fontEpoch = useTextViewerFontEpoch()
  const [contentWidth, setContentWidth] = React.useState(
    TEXT_VIEWER_INITIAL_TEXT_WIDTH
  )

  const preparedDocument = React.useMemo(
    () =>
      createPreparedTextDocument({
        mode,
        style: { fontScale: 1 },
        text,
      }),
    [fontEpoch, mode, text]
  )
  const frame = React.useMemo(
    () =>
      layoutTextDocument({
        contentWidth,
        document: preparedDocument,
        fontScale,
      }),
    [contentWidth, fontScale, preparedDocument]
  )
  const highlightStart = highlight?.start
  const highlightEnd = highlight?.end
  const highlightRange = React.useMemo(
    () =>
      normalizeTextLineRange(
        highlightStart == null || highlightEnd == null
          ? null
          : { end: highlightEnd, start: highlightStart },
        preparedDocument.sourceLineCount
      ),
    [highlightEnd, highlightStart, preparedDocument.sourceLineCount]
  )
  const captureScrollAnchor = React.useCallback(() => {
    pendingScrollAnchorRef.current = getTextFrameScrollAnchor({
      frames: frame.frames,
      scrollTop: viewportRef.current?.scrollTop ?? 0,
    })
  }, [frame.frames])

  React.useLayoutEffect(() => {
    const nextContentWidth = Math.max(
      1,
      viewportWidth - TEXT_VIEWER_HORIZONTAL_PADDING * 2
    )
    setContentWidth((current) => {
      if (current === nextContentWidth) return current
      captureScrollAnchor()
      return nextContentWidth
    })
  }, [captureScrollAnchor, viewportWidth])

  React.useLayoutEffect(() => {
    const anchor = pendingScrollAnchorRef.current
    const scrollElement = viewportRef.current
    if (!anchor || !scrollElement) return

    pendingScrollAnchorRef.current = null
    const nextFrame = frame.frames[anchor.index]
    if (!nextFrame) return

    scrollElement.scrollTop = Math.max(
      0,
      nextFrame.top +
        Math.min(anchor.offsetWithinFrame, Math.max(0, nextFrame.height - 1))
    )
  }, [frame.frames])

  const scrollLineRange = React.useCallback(
    (
      range: ReturnType<typeof normalizeTextLineRange>,
      options?: ScrollToOptions
    ) => {
      const scrollElement = viewportRef.current
      if (!scrollElement || !range) return

      const targetFrame =
        frame.frames.find((item) =>
          textFrameIntersectsLineRange({ frame: item, range })
        ) ?? frame.frames[0]
      if (!targetFrame) return

      const targetTop =
        targetFrame.height <= scrollElement.clientHeight
          ? targetFrame.top -
            (scrollElement.clientHeight - targetFrame.height) / 2
          : targetFrame.top

      scrollElement.scrollTo({
        behavior: "smooth",
        top: Math.max(0, targetTop),
        ...options,
      })
    },
    [frame.frames]
  )

  const zoom = (factor: number) => {
    captureScrollAnchor()
    setFontScale((scale) => clampTextViewerScale(scale * factor))
  }

  const resetZoom = () => {
    captureScrollAnchor()
    setFontScale(1)
  }

  React.useImperativeHandle(
    forwardedRef ?? null,
    () => ({
      getViewportElement: () => viewportRef.current,
      scrollToLineRange: (range, options) => {
        scrollLineRange(
          normalizeTextLineRange(range, preparedDocument.sourceLineCount),
          options
        )
      },
    }),
    [preparedDocument.sourceLineCount, scrollLineRange]
  )

  React.useEffect(() => {
    scrollLineRange(highlightRange)
  }, [highlightRange, scrollLineRange])

  const scrollMarkdownFragment = React.useCallback(
    (event: React.MouseEvent) => {
      const href = localFragmentHrefFromEventTarget(event.target)
      if (!href) return

      const targetId = decodeMarkdownFragmentHref(href)
      const targetIndex = markdownHeadingBlockIndex(
        preparedDocument.blocks,
        targetId
      )
      const targetFrame = frame.frames[targetIndex]
      const scrollElement = viewportRef.current
      if (!targetFrame || !scrollElement) return

      event.preventDefault()
      scrollElement.scrollTo({
        behavior: "smooth",
        top: Math.max(0, targetFrame.top),
      })
      if (window.location.hash !== href) {
        window.history.replaceState(null, "", href)
      }
    },
    [frame.frames, preparedDocument.blocks]
  )

  return (
    <TextViewerFrame className={className} bare={bare}>
      {toolbar ? (
        <TextViewerToolbar
          wordCount={preparedDocument.wordCount}
          fontScale={fontScale}
          downloadAction={downloadAction}
          onZoomOut={() => zoom(1 / 1.2)}
          onZoomIn={() => zoom(1.2)}
          onResetZoom={resetZoom}
        />
      ) : null}
      <ScrollArea
        className="min-h-0 flex-1 bg-background"
        orientation="vertical"
        viewportClassName="bg-background"
        viewportProps={{ onClickCapture: scrollMarkdownFragment }}
        viewportRef={viewportRef}
      >
        <TextVirtualCanvas
          contentWidth={contentWidth}
          document={preparedDocument}
          frame={frame}
          highlightRange={highlightRange}
          scrollTop={viewport.scrollTop}
          viewportHeight={viewportHeight}
          viewportWidth={viewportWidth}
        />
      </ScrollArea>
    </TextViewerFrame>
  )
}

type TextVirtualCanvasProps = {
  contentWidth: number
  document: PreparedTextDocument
  frame: TextDocumentFrame
  highlightRange: ReturnType<typeof normalizeTextLineRange>
  scrollTop: number
  viewportHeight: number
  viewportWidth: number
}

const TextVirtualCanvas = React.memo(
  TextVirtualCanvasImpl,
  areTextVirtualCanvasPropsEqual
)

function TextVirtualCanvasImpl({
  contentWidth,
  document,
  frame,
  highlightRange,
  scrollTop,
  viewportHeight,
  viewportWidth,
}: TextVirtualCanvasProps) {
  const virtualItems = React.useMemo(
    () =>
      getTextFrameVirtualItems({
        frames: frame.frames,
        overscanPx: TEXT_VIEWER_OVERSCAN_PX,
        scrollTop,
        viewportHeight,
      }),
    [frame.frames, scrollTop, viewportHeight]
  )
  const viewportTop = scrollTop - TEXT_VIEWER_OVERSCAN_PX
  const viewportBottom = scrollTop + viewportHeight + TEXT_VIEWER_OVERSCAN_PX

  return (
    <div
      className="relative min-w-0"
      data-slot="text-virtual-canvas"
      style={{
        height: frame.totalHeight,
        minWidth: viewportWidth,
      }}
    >
      {virtualItems.map((item) => {
        const block = document.blocks[item.index]
        const blockFrame = frame.frames[item.index]
        if (!block || !blockFrame) return null
        return (
          <TextBlock
            key={item.index}
            block={block}
            contentWidth={contentWidth}
            frame={blockFrame}
            highlightRange={highlightRange}
            viewportBottom={viewportBottom}
            viewportTop={viewportTop}
          />
        )
      })}
    </div>
  )
}

function areTextVirtualCanvasPropsEqual(
  previous: TextVirtualCanvasProps,
  next: TextVirtualCanvasProps
) {
  return (
    previous.contentWidth === next.contentWidth &&
    previous.document === next.document &&
    previous.frame === next.frame &&
    previous.viewportHeight === next.viewportHeight &&
    previous.viewportWidth === next.viewportWidth &&
    isSameHighlightRange(previous.highlightRange, next.highlightRange) &&
    textProjectionWindowKey(
      previous.frame.frames,
      previous.scrollTop,
      previous.viewportHeight
    ) ===
      textProjectionWindowKey(
        next.frame.frames,
        next.scrollTop,
        next.viewportHeight
      )
  )
}

type TextBlockProps = {
  block: PreparedTextBlock
  contentWidth: number
  frame: TextBlockFrame
  highlightRange: ReturnType<typeof normalizeTextLineRange>
  viewportBottom: number
  viewportTop: number
}

const TextBlock = React.memo(TextBlockImpl, areTextBlockPropsEqual)

function TextBlockImpl({
  block,
  contentWidth,
  frame,
  highlightRange,
  viewportBottom,
  viewportTop,
}: TextBlockProps) {
  if (block.kind !== frame.kind) {
    if (process.env.NODE_ENV !== "production") {
      throw new Error(
        `Text viewer block/frame mismatch: block=${block.kind}, frame=${frame.kind}`
      )
    }
    return null
  }

  const isHighlighted =
    frame.sourceStartLine === frame.sourceEndLine
      ? isLineInRange(frame.sourceStartLine, highlightRange)
      : textFrameIntersectsLineRange({ frame, range: highlightRange })

  switch (block.kind) {
    case "inline":
      return (
        <InlineTextBlock
          block={block}
          contentWidth={contentWidth}
          frame={frame as InlineTextBlockFrame}
          isHighlighted={isHighlighted}
          viewportBottom={viewportBottom}
          viewportTop={viewportTop}
        />
      )
    case "code":
      return (
        <CodeTextBlock
          block={block}
          contentWidth={contentWidth}
          frame={frame as CodeTextBlockFrame}
          isHighlighted={isHighlighted}
          viewportBottom={viewportBottom}
          viewportTop={viewportTop}
        />
      )
    case "image":
      return (
        <ImageTextBlock
          block={block}
          frame={frame as ImageTextBlockFrame}
          isHighlighted={isHighlighted}
        />
      )
    case "rule":
      return (
        <RuleTextBlock
          block={block}
          frame={frame as RuleTextBlockFrame}
          isHighlighted={isHighlighted}
        />
      )
    case "table":
      return (
        <TableTextBlock
          block={block}
          frame={frame as TableTextBlockFrame}
          isHighlighted={isHighlighted}
          viewportBottom={viewportBottom}
          viewportTop={viewportTop}
        />
      )
  }
}

function areTextBlockPropsEqual(
  previous: TextBlockProps,
  next: TextBlockProps
) {
  return (
    previous.block === next.block &&
    previous.frame === next.frame &&
    previous.contentWidth === next.contentWidth &&
    isSameHighlightRange(previous.highlightRange, next.highlightRange) &&
    textBlockVisibleWindowKey(
      previous.frame,
      previous.viewportTop,
      previous.viewportBottom
    ) ===
      textBlockVisibleWindowKey(
        next.frame,
        next.viewportTop,
        next.viewportBottom
      )
  )
}

function isSameHighlightRange(
  a: ReturnType<typeof normalizeTextLineRange>,
  b: ReturnType<typeof normalizeTextLineRange>
) {
  return (
    a === b ||
    (a != null && b != null && a.start === b.start && a.end === b.end)
  )
}

function textProjectionWindowKey(
  frames: readonly TextBlockFrame[],
  scrollTop: number,
  viewportHeight: number
) {
  const viewportTop = scrollTop - TEXT_VIEWER_OVERSCAN_PX
  const viewportBottom = scrollTop + viewportHeight + TEXT_VIEWER_OVERSCAN_PX
  return getTextFrameVirtualItems({
    frames,
    overscanPx: TEXT_VIEWER_OVERSCAN_PX,
    scrollTop,
    viewportHeight,
  })
    .map((item) => {
      const frame = frames[item.index]
      if (!frame) return `${item.index}:missing`
      return `${item.index}:${textBlockVisibleWindowKey(
        frame,
        viewportTop,
        viewportBottom
      )}`
    })
    .join("|")
}

function textBlockVisibleWindowKey(
  frame: TextBlockFrame,
  viewportTop: number,
  viewportBottom: number
) {
  switch (frame.kind) {
    case "inline":
      return lineWindowKey(
        getInlineVisibleLineWindow({
          frame,
          viewportBottom,
          viewportTop,
        })
      )
    case "code":
      return lineWindowKey(
        getCodeVisibleLineWindow({
          frame,
          viewportBottom,
          viewportTop,
        })
      )
    case "table":
      return tableRowWindowKey(
        getTableVisibleRowWindow({
          frame,
          viewportBottom,
          viewportTop,
        })
      )
    case "image":
    case "rule":
      return "static"
  }
}

function lineWindowKey(window: TextLineWindow | null) {
  return window ? `${window.firstLine}:${window.lastLine}` : "none"
}

function tableRowWindowKey(window: TableRowWindow) {
  return `${window.startIndex}:${window.endIndex}`
}

function InlineTextBlock({
  block,
  contentWidth,
  frame,
  isHighlighted,
  viewportBottom,
  viewportTop,
}: {
  block: PreparedInlineTextBlock
  contentWidth: number
  frame: InlineTextBlockFrame
  isHighlighted: boolean
  viewportBottom: number
  viewportTop: number
}) {
  const lines = materializeInlineVisibleLines({
    block,
    frame,
    maxWidth: contentWidth,
    viewportBottom,
    viewportTop,
  })
  const headingLevel = inlineHeadingLevel(block)
  const role =
    headingLevel == null && frame.markerText
      ? "listitem"
      : headingLevel == null
        ? undefined
        : "heading"
  const ariaLevel =
    headingLevel ?? (frame.markerText ? frame.listDepth : undefined)

  return (
    <div
      className={cn(
        "absolute left-0 w-full px-4",
        isHighlighted && "bg-primary/12 ring-1 ring-primary/30 ring-inset"
      )}
      data-slot="text-line"
      data-source-line={frame.sourceStartLine}
      data-list-depth={frame.listDepth || undefined}
      data-quote-depth={frame.quoteDepth || undefined}
      role={role}
      aria-level={ariaLevel}
      id={block.headingId ?? undefined}
      data-heading-id={block.headingId ?? undefined}
      style={{
        height: frame.height,
        transform: `translateY(${frame.top}px)`,
      }}
    >
      <BlockChrome frame={frame} />
      {lines.map((line, index) => (
        <div
          key={`${line.top}-${index}`}
          className="absolute flex w-max items-center gap-0"
          style={{
            height: frame.lineHeight,
            left: 16 + frame.contentLeft,
            top: line.top,
            transform: `scale(${frame.scale})`,
            transformOrigin: "left top",
          }}
        >
          {line.fragments.map((fragment, fragmentIndex) => {
            const style =
              fragment.leadingGap > 0
                ? {
                    font: fragment.font,
                    letterSpacing: 0,
                    marginLeft: fragment.leadingGap,
                  }
                : { font: fragment.font, letterSpacing: 0 }
            if (fragment.href) {
              const isFragment = isLocalFragmentHref(fragment.href)
              return (
                <a
                  key={fragmentIndex}
                  className={fragment.className}
                  href={fragment.href}
                  rel={isFragment ? undefined : "noopener noreferrer"}
                  style={style}
                  target={isFragment ? undefined : "_blank"}
                  title={fragment.title ?? undefined}
                >
                  {fragment.text}
                </a>
              )
            }
            return (
              <span
                key={fragmentIndex}
                className={fragment.className}
                style={style}
              >
                {fragment.text}
              </span>
            )
          })}
        </div>
      ))}
    </div>
  )
}

function useTextViewerFontEpoch() {
  const [fontEpoch, setFontEpoch] = React.useState(0)

  React.useEffect(() => {
    const fonts = document.fonts
    if (!fonts) return

    let isMounted = true
    void fonts.ready.then(() => {
      if (isMounted) setFontEpoch((epoch) => epoch + 1)
    })

    return () => {
      isMounted = false
    }
  }, [])

  return fontEpoch
}

function inlineHeadingLevel(block: PreparedInlineTextBlock) {
  if (block.variant === "heading-1") return 1
  if (block.variant === "heading-2") return 2
  return undefined
}

